INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT107-S3-Q13$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Darla, implied) There is no good reason to think air pollution from cars falls during a recession.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$In a recession, fewer people buy new cars, and older cars pollute more.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Charles's logic is: fewer people commute, so fewer cars on the road, so less pollution. Darla does not deny that. She adds a factor pushing the other way: the cars still on the road are older and dirtier. With a force on each side, Charles's evidence no longer guarantees his conclusion.$batch05$), (3, $batch05$Goal$batch05$, $batch05$Adding a consideration that weakens the support Charles's evidence gives his conclusion.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT107-S3-Q13$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Darla does not dispute that unemployment rises or that fewer people commute.$batch05$), ($batch05$B$batch05$, $batch05$Darla's point does not *contradict* Charles's conclusion. Fewer cars could still mean less pollution overall, even with dirtier cars. Her point only makes the result uncertain.$batch05$), ($batch05$C$batch05$, $batch05$The additional consideration is older, dirtier cars. It weakens the link from "fewer commuters" to "less pollution" without denying either.$batch05$), ($batch05$D$batch05$, $batch05$Darla doubts Charles's conclusion. She does not argue it is true for other reasons.$batch05$), ($batch05$E$batch05$, $batch05$This is the most popular wrong answer. But Darla does not use Charles's premises to reach something absurd. She brings in a new fact of her own.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT107-S3-Q13$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
